def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_def = sum(1 for h in history if h[1] == 'D')

    if opp_def == 0:
        if n >= 20:
            return 'D'
        if n % 2 == 1:
            return 'D'
        return 'C'

    if opp_def * 2 > n:
        return 'D'

    return 'C'
